import {genreNames,typeNames,titleOf,descriptions,filterCatalog,safeUrl,videoUrl,escapeHtml as e} from './domain.mjs';
const main=document.querySelector('main'),query=document.querySelector('#query');
let catalog=[],streams={};
const imageHosts=['cdn.myanimelist.net','media.kitsu.app','media.kitsu.io','s4.anilist.co','s.anilist.co','cdn.anisearch.com','i.ytimg.com','thumb.wikimedia.org','upload.wikimedia.org'];
const imageUrl=value=>safeUrl(value,imageHosts)||'favicon.svg';
const external=(url,label)=>`<a href="${e(url)}" target="_blank" rel="noopener">${label}</a>`;
const number=n=>new Intl.NumberFormat('ru-RU').format(n);
function current(){const raw=location.hash.slice(1)||'/';const [path,search='']=raw.split('?');return{path,params:new URLSearchParams(search)};}
function routeUrl(path,values){const p=new URLSearchParams();for(const [k,v]of Object.entries(values))if(v!==''&&v!==false&&v!=null)p.set(k,String(v));return '#'+path+(p.size?'?'+p:'');}
function updateFilters(values){const {path,params}=current();const next={...Object.fromEntries(params),...values,page:''};location.hash=routeUrl(path==='/watch'?'/watch':'/',next).slice(1);}
function card(a){return `<a class="card" href="#/anime/${a.id}" aria-label="${e(titleOf(a))}"><div class="poster"><img src="${e(imageUrl(a.image))}" alt="Обложка: ${e(titleOf(a))}" loading="lazy" width="240" height="342"><span class="score">★ ${a.score?a.score.toFixed(1):'—'}</span>${streams[a.id]?.length?'<span class="playable-tag">▷ Есть полные серии</span>':''}</div><h3>${e(titleOf(a))}</h3><div class="card-meta"><span>${a.year||'Год неизвестен'}</span><span>·</span><span>${e(typeNames[a.type]||a.type)}</span><span>·</span><span>${a.episodes?e(a.episodes)+' эп.':'—'}</span></div></a>`;}
function feature(){const thumbnail=streams[40861]?.[0]?.thumbnail;return `<section class="feature" aria-label="Доступно для просмотра">${thumbnail?`<img src="${e(imageUrl(thumbnail))}" alt="Кадр из Pokémon: Сумеречные крылья" fetchpriority="high">`:''}<div class="feature-content"><span class="eyebrow">СЕМЬ ИСТОРИЙ. ОДИН БОЛЬШОЙ МИР.</span><h2>Pokémon:<br><span>Сумеречные крылья</span></h2><div class="pills"><span class="pill live">Все 7 серий</span><span class="pill">2020</span><span class="pill">Веб-сериал</span><span class="pill">EN</span></div><p>Маленькие истории о больших мечтах.<br>Открой другую сторону Галара.</p><a class="button" href="#/anime/40861?ep=1&play=1"><span aria-hidden="true">▶</span> Смотреть первую серию</a></div></section>`;}
function option(value,label,selected){return `<option value="${e(value)}" ${String(value)===String(selected)?'selected':''}>${e(label)}</option>`;}
function renderCatalog(path,params){
 const q=params.get('q')||'',genre=params.get('genre')||'',type=params.get('type')||'',year=params.get('year')||'',sort=params.get('sort')||'',watch=path==='/watch'||params.get('watch')==='true';
 query.value=q;
 const filtered=filterCatalog(catalog,{q,genre,type,year,sort,watch},streams),pages=Math.max(1,Math.ceil(filtered.length/24)),page=Math.min(pages,Math.max(1,Number.parseInt(params.get('page'))||1));
 const years=[...new Set(catalog.map(a=>a.year).filter(Boolean))].sort((a,b)=>b-a);
 const clean=!q&&!genre&&!type&&!year&&!watch&&!sort&&page===1;
 main.innerHTML=`<div class="page-heading"><h1>${path==='/watch'?'Смотреть аниме':q?'Результаты поиска':'Твой следующий аниме-вечер'}</h1><span class="heading-note">Найди историю под настроение</span></div>${clean?feature():''}${path==='/watch'?'<p class="catalog-intro">Тайтлы с подключёнными полными выпусками. Источник и язык указаны на странице просмотра.</p>':''}<section aria-labelledby="catalog-title"><div class="catalog-head"><h2 id="catalog-title">${q?'По запросу «'+e(q)+'»':'Каталог аниме'}<span class="count">${number(filtered.length)}</span></h2><span class="heading-note">Собрано для хороших вечеров</span></div><div class="filterbar"><label>ЖАНР<select id="genre">${option('','Все жанры',genre)}${Object.entries(genreNames).map(([k,v])=>option(k,v,genre)).join('')}</select></label><label>ФОРМАТ<select id="type">${option('','Все форматы',type)}${Object.entries(typeNames).filter(([k])=>catalog.some(a=>a.type===k)).map(([k,v])=>option(k,v,type)).join('')}</select></label><label>ГОД<select id="year">${option('','Все годы',year)}${years.map(y=>option(y,y,year)).join('')}</select></label><label>СОРТИРОВКА<select id="sort">${[['','Выбор редакции'],['score','По рейтингу'],['year','Сначала новые'],['title','По названию']].map(([k,v])=>option(k,v,sort)).join('')}</select></label><button class="reset" id="reset">Сбросить</button>${path!=='/watch'?`<button class="watch-filter ${watch?'selected':''}" id="watch-filter" aria-pressed="${watch}">▷ Только с сериями</button>`:''}</div><div id="result-status" class="sr-only" role="status">Найдено: ${filtered.length}. Страница ${page} из ${pages}.</div>${filtered.length?`<div class="grid">${filtered.slice((page-1)*24,page*24).map(card).join('')}</div><div class="pagination"><button id="previous" ${page===1?'disabled':''}>← Назад</button><span>${page} / ${pages}</span><button id="next" ${page===pages?'disabled':''}>Дальше →</button></div>`:'<div class="empty"><h2>Такого аниме пока нет</h2><p>Попробуй другое название, оригинальное написание или убери часть фильтров.</p><button class="button secondary" id="empty-reset">Сбросить поиск</button></div>'}</section>`;
 for(const field of ['genre','type','year','sort'])document.getElementById(field).addEventListener('change',event=>updateFilters({[field]:event.target.value}));
 const reset=()=>{document.querySelector('#search').reset();location.hash=path==='/watch'?'/watch':'/';};
 document.querySelector('#reset').onclick=reset;document.querySelector('#empty-reset')?.addEventListener('click',reset);
 document.querySelector('#watch-filter')?.addEventListener('click',()=>updateFilters({watch:!watch}));
 for(const [id,offset] of [['previous',-1],['next',1]])document.getElementById(id)?.addEventListener('click',()=>{location.hash=routeUrl(path,{...Object.fromEntries(params),page:page+offset}).slice(1);window.scrollTo({top:0,behavior:'instant'});});
 document.title=q?`${q} — HikkiAnime`:'HikkiAnime — твой аниме-вечер';
}
function renderDetail(id,params){
 const a=catalog.find(a=>a.id===id);
 if(!a){main.innerHTML='<div class="empty"><h1>Аниме не найдено</h1><p>Возможно, ссылка ведёт на тайтл вне этой подборки.</p><a class="button" href="#/">Вернуться в каталог</a></div>';return;}
 query.value='';
 const episodes=streams[id]||[],requested=Number(params.get('ep'))||1,episode=episodes.find(x=>x.number===requested)||episodes[0];
 const synopsis=descriptions[id];
 main.innerHTML=`<a class="back" href="#/">← В каталог</a><section class="detail-top"><img class="detail-poster" src="${e(imageUrl(a.image))}" alt="Обложка: ${e(titleOf(a))}"><div class="detail-info"><span class="eyebrow">${e(typeNames[a.type])} / ${a.year||'—'}</span><h1>${e(titleOf(a))}</h1><p class="original-title">${e(a.title)}</p><div class="pills"><span class="pill live">★ ${a.score.toFixed(1)} · сводный рейтинг</span>${a.genres.slice(0,4).map(g=>`<a class="pill" href="${routeUrl('/',{genre:g})}">${e(genreNames[g])}</a>`).join('')}</div><dl class="facts"><div><dt>ВЫПУСКОВ</dt><dd>${a.episodes||'Неизвестно'}</dd></div><div><dt>СТАТУС</dt><dd>${e({FINISHED:'Завершён',ONGOING:'Выходит',UPCOMING:'Анонсирован'}[a.status]||'Неизвестно')}</dd></div><div><dt>СТУДИЯ</dt><dd>${e(a.studios.join(', ')||'Не указана')}</dd></div></dl><span class="source-link">${external(safeUrl(a.source,['myanimelist.net']), 'Карточка на MyAnimeList ↗')}</span></div>${synopsis?`<p class="synopsis">${e(synopsis)}</p>`:''}</section>${episode?`<section class="watch-layout" aria-label="Просмотр серий"><div><div class="player" id="player"><img src="${e(imageUrl(episode.thumbnail))}" alt="Серия ${episode.number}: ${e(episode.title)}"><button class="button" id="play"><span aria-hidden="true">▶</span> Смотреть серию ${episode.number}</button></div><div class="player-actions"><strong>Серия ${episode.number} · ${e(episode.title)}</strong>${episode.number<episodes.length?`<a href="#/anime/${id}?ep=${episode.number+1}&play=1">Следующая серия →</a>`:'<span class="muted">Просмотр до конца</span>'}</div><p class="player-note">${e(episode.language)} · ${e(episode.publisher)}<br>${episode.provider==='wikimedia'?e(episode.credit)+' '+external(episode.licenseUrl,'CC BY 3.0 ↗')+' · '+external(episode.musicSource,'Музыка ↗')+' · '+external(episode.source,'Страница источника ↗'):'При недоступности встроенного видео '+external(episode.source,'открой выпуск на YouTube ↗')+'. Доступность, субтитры и качество зависят от YouTube и региона.'}</p></div><aside class="episodes"><h2>Все серии</h2><p>${episodes.length} выпусков · ${e(episode.provider==='wikimedia'?'Классика':'Английский')}</p><nav class="episode-list" aria-label="Выбор серии">${episodes.map(x=>`<a href="#/anime/${id}?ep=${x.number}&play=1" aria-current="${x.number===episode.number}"><span>${String(x.number).padStart(2,'0')}</span>${e(x.title)}</a>`).join('')}</nav></aside></section>`:`<section class="detail-empty"><div><h2>Серии ещё не подключены</h2><p>Информация об аниме уже есть в каталоге. Для этого тайтла пока нет подключённого источника полных выпусков.</p></div><a class="button secondary" href="#/watch">Что можно посмотреть</a></section>`}`;
 if(episode){const start=()=>{if(episode.provider==='wikimedia'){const video=document.createElement('video');video.controls=true;video.playsInline=true;video.preload='metadata';video.poster=imageUrl(episode.thumbnail);video.src=safeUrl(episode.mediaUrl,['upload.wikimedia.org']);video.setAttribute('aria-label',titleOf(a));video.addEventListener('error',()=>{const note=document.createElement('p');note.className='player-note error-message';note.textContent='Видео не загрузилось. Открой страницу источника по ссылке ниже.';document.querySelector('#player').after(note);},{once:true});document.querySelector('#player').replaceChildren(video);video.play().catch(()=>{});return;}const url=new URL(videoUrl(episode.videoId));url.searchParams.set('autoplay','1');url.searchParams.set('rel','0');url.searchParams.set('playsinline','1');const frame=document.createElement('iframe');frame.src=url.href;frame.title=`${titleOf(a)} — серия ${episode.number}: ${episode.title}`;frame.allow='accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; fullscreen';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';document.querySelector('#player').replaceChildren(frame);};document.querySelector('#play').onclick=start;if(params.get('play')==='1')start();}
 document.title=`${titleOf(a)} — HikkiAnime`;
}
function render(){const{path,params}=current();document.querySelectorAll('[data-nav]').forEach(a=>{const active=(a.dataset.nav==='watch'&&path==='/watch')||(a.dataset.nav==='catalog'&&path==='/');if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});const match=path.match(/^\/anime\/(\d+)$/);if(match){renderDetail(Number(match[1]),params);window.scrollTo(0,0);}else if(path==='/'||path==='/watch'){renderCatalog(path,params);}else{main.innerHTML='<div class="empty"><h1>Страница не найдена</h1><a class="button" href="#/">Открыть каталог</a></div>';}}
document.querySelector('.skip').onclick=event=>{event.preventDefault();main.focus();main.scrollIntoView();};
document.querySelector('#search').onsubmit=event=>{event.preventDefault();const q=query.value.trim();const {path,params}=current();location.hash=routeUrl(path==='/watch'?'/watch':'/',{...(path==='/'||path==='/watch'?Object.fromEntries(params):{}),q,page:''}).slice(1);window.scrollTo(0,0);};
for(const id of ['about','sources'])document.getElementById(id).onclick=()=>document.querySelector('dialog').showModal();
document.querySelector('dialog').addEventListener('click',event=>{if(event.target===event.currentTarget){const rect=event.currentTarget.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)event.currentTarget.close();}});
document.addEventListener('error',event=>{if(event.target instanceof HTMLImageElement&&!event.target.classList.contains('image-failed')){event.target.classList.add('image-failed');event.target.src='favicon.svg';}},true);
window.addEventListener('hashchange',()=>{if(catalog.length)render();});
async function init(){try{const results=await Promise.all(['data/catalog.json','data/episodes.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw Error('HTTP '+r.status);return r.json();}));catalog=results[0].data;streams=results[1].series;if(!Array.isArray(catalog)||!catalog.length)throw Error('Empty catalog');render();}catch{main.innerHTML='<div class="empty"><h1>Каталог не загрузился</h1><p>Проверь подключение и попробуй ещё раз.</p><button class="button" id="retry">Повторить</button></div>';document.querySelector('#retry').onclick=init;}}
init();
